// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address ownerActor) public {
        vm.assume(ownerActor != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(address(this), 2 ether);
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent);

        Reverter rev = new Reverter();

        bool ok;
        try c.sendMoney(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
